import json
from pathlib import Path
R=Path(__file__).resolve().parents[1];S=json.loads((R/'selection.json').read_text());B=json.loads(json.dumps(S))
def g(n):return next(s for s in S if s['name']==n)
s=g('金属与稀盐酸、稀硫酸的反应及探究');s['regions'][2]=[17,57,118,185,480];s['detail']='很多金属不仅能与氧气反应，还能与稀盐酸或稀硫酸反应。金属能否与稀盐酸或稀硫酸反应，可反映金属的活动性。\n\n【实验】\n\n（1）在试管中放入少量镁，加入5 mL稀盐酸，将燃着的木条放在试管口，观察现象，并判断反应后生成了什么气体。\n\n参照上述实验步骤，分别向盛有少量锌、铁、铜的试管中加入5 mL稀盐酸，观察现象（如图8-10）。如果有气体生成，判断生成的是什么气体。\n\n（2）用稀硫酸代替稀盐酸进行上述实验。\n\n在上述探究中，镁、锌、铁能与稀盐酸、稀硫酸发生反应，反应都生成可燃性气体——氢气，而铜不能与稀盐酸、稀硫酸反应。\n\n通过上述探究还可以得出，镁、锌、铁的金属活动性比铜的强，它们能置换出稀盐酸或稀硫酸中的氢。'
g('常见金属的物理性质与用途')['detail']=g('常见金属的物理性质与用途')['detail'].replace('1. 金属','金属')
